#!/usr/bin/env bash
# Patches the Runner projects generated by `flutter create` for AR scanning.
# Safe to run more than once.
set -euo pipefail
cd "$(dirname "$0")/.."

# --- Android: ARCore needs minSdk 24 -----------------------------------------
for f in android/app/build.gradle.kts android/app/build.gradle; do
  [ -f "$f" ] || continue
  sed -i.bak -E 's/minSdk(Version)?( =)? flutter\.minSdkVersion/minSdk\1\2 24/' "$f"
  rm -f "$f.bak"
  echo "✓ $f: minSdk 24"
done

# --- iOS: deployment target 14.0 + camera permission text --------------------
PBX=ios/Runner.xcodeproj/project.pbxproj
if [ -f "$PBX" ]; then
  sed -i.bak -E 's/IPHONEOS_DEPLOYMENT_TARGET = 1[0-3]\.[0-9]+;/IPHONEOS_DEPLOYMENT_TARGET = 14.0;/g' "$PBX"
  rm -f "$PBX.bak"
  echo "✓ $PBX: deployment target 14.0"
fi

if [ -f ios/Runner/Info.plist ]; then
  PYTHONIOENCODING=utf-8 python3 - <<'PY'
import pathlib, plistlib
p = pathlib.Path("ios/Runner/Info.plist")
d = plistlib.loads(p.read_bytes())
d["NSCameraUsageDescription"] = "Scan3D uses the camera to build a 3D map of your surroundings."
caps = d.get("UIRequiredDeviceCapabilities", [])
if isinstance(caps, list) and "arkit" not in caps:
    caps.append("arkit")
    d["UIRequiredDeviceCapabilities"] = caps
p.write_bytes(plistlib.dumps(d))
print("✓ ios/Runner/Info.plist: camera usage + arkit capability")
PY
fi

echo "Done."
